<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\SnippetVersion\Application\Usecase\Create;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Features\Document\SnippetVersion\Application\Service\Visibility\SnippetVersionVisibilityService;
use Civi\Lughauth\Features\Document\SnippetVersion\Domain\SnippetVersion;
use Civi\Lughauth\Features\Document\SnippetVersion\Domain\Gateway\SnippetVersionCommandRepositoryGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class SnippetVersionCreateUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly SnippetVersionVisibilityService $visibility,
        private readonly SnippetVersionCommandRepositoryGateway $writer,
    ) {
    }

    public function allowCreate(): Allow
    {
        $this->logDebug("Check allow of create usecase for Snippet version");
        $span = $this->startSpan("Check allow of create usecase for Snippet version");
        try {
            $result = $this->dispatcher->dispatch(new SnippetVersionCreateAllowDecision(Allow::allowed('create', 'Allowed to create by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function create(SnippetVersionCreateParams $params): SnippetVersionCreateResult
    {
        $this->logDebug("Run create usecase for Snippet version");
        $span = $this->startSpan("Run create usecase for Snippet version");
        try {
            $allow = $this->allowCreate();
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to create Snippet version');
            }
            $this->dispatcher->dispatch(new SnippetVersionCreateCheck($params));
            $attributes = $this->visibility->copyWithFixed($params->toAttributes());
            $enriched = $this->dispatcher->dispatch(new SnippetVersionCreateEnrich($params, $attributes));
            $input = $enriched->getEnrichedAttributes();
            $entity = SnippetVersion::create($input);
            $result = $this->writer->create(
                $entity,
                fn (SnippetVersion $created) =>
                            $this->visibility->checkVisibility($created)
            );
            $output = $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($result));
            return new SnippetVersionCreateResult($output);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
